import numpy as np


def maxpool2d(x, size):
    x = np.asarray(x, dtype=float)
    h, w = x.shape
    return x.reshape(h // size, size, w // size, size).max(axis=(1, 3))


def avgpool2d(x, size):
    x = np.asarray(x, dtype=float)
    h, w = x.shape
    return x.reshape(h // size, size, w // size, size).mean(axis=(1, 3))

